{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "苏清宁",
      "role": "protagonist",
      "identity": "前豪门儿媳，古董鉴定师，出身文物修复世家",
      "traits": ["冷静理智", "专业偏执", "嘴硬心软", "轻度社恐"],
      "overt_motivation": "守住永乐青花罐，在古董行站稳脚跟，反击前夫家族的恶意追讨",
      "covert_motivation": "证明自己的专业价值不是豪门的点缀，获得行业和自我的双重认可",
      "secret_fear": "害怕自己的专业判断出错，重蹈三年豪门生活中被否定的自我怀疑",
      "misperception_of_other": "以为陆时衍接近自己只是为了永乐青花罐的利益",
      "hidden_connection": "外公陈敬之当年修复永乐官窑残件时，陆时衍的爷爷曾是故宫的同事"
    },
    {
      "name": "陆时衍",
      "role": "deuteragonist",
      "identity": "民营古董行\"时斋\"的老板，资深古董鉴定师",
      "traits": ["表面腹黑", "内心正直", "专业严谨", "不擅表达"],
      "overt_motivation": "和苏清宁合作，打击古董行的造假乱象，维护行业规则",
      "covert_motivation": "弥补当年爷爷没能保住完整永乐青花罐的遗憾，保护苏清宁不被行业老狐狸坑害",
      "secret_fear": "害怕自己的过去投资失败的黑历史被曝光，连累苏清宁的声誉",
      "misperception_of_other": "以为苏清宁对自己只有商业合作的想法，没有好感",
      "hidden_connection": "爷爷和苏清宁的外公陈敬之是同门师兄弟"
    }
  ],
  "supporting_characters": [
    {
      "name": "周子豪",
      "function": "阻碍",
      "identity": "苏清宁的前夫，周氏集团继承人",
      "description": "纨绔富二代，大男子主义，看不起苏清宁的专业，离婚后发现青花罐价值后悔不当初，用尽手段想要夺回"
    },
    {
      "name": "冯美兰",
      "function": "阻碍",
      "identity": "周子豪的母亲，周氏集团董事",
      "description": "强势精明的豪门主母，当初招苏清宁进门只是为了撑场面，发现青花罐价值后不惜用法律手段和灰色操作抢回"
    },
    {
      "name": "陈敬之",
      "function": "助力",
      "identity": "苏清宁的外公，故宫退休陶瓷修复大师",
      "description": "一辈子和文物打交道，性格耿直，是苏清宁专业上的启蒙者和精神支柱，手里有当年修复永乐官窑残件的全套记录"
    },
    {
      "name": "张百川",
      "function": "反转点",
      "identity": "古董行资深老板，行业泰斗级人物",
      "description": "表面德高望重，实际靠造假发家，一开始想坑苏清宁的青花罐，后来被苏清宁和陆时衍抓住造假证据，反水指证周氏家族的非法操作"
    },
    {
      "name": "林薇薇",
      "function": "助力",
      "identity": "知识产权+文物相关的专业律师",
      "description": "苏清宁的大学同学，性格飒爽，精通文物相关的法律法规，帮苏清宁打和前夫家的官司"
    }
  ],
  "relationship_dynamics": "苏清宁和陆时衍初期因古董鉴定事件结识，互相试探不信任，中期因为共同对抗张百川和周氏家族而成为盟友，慢慢产生好感但都不说破，经历信任危机后坦诚心意，最终成为事业和生活上的平等伙伴；苏清宁和周子豪、冯美兰从前期的表面和平到离婚后的彻底敌对，在法律和商业战场上正面交锋；张百川前期和周氏家族勾结坑害苏清宁，后期为了自保反水，成为反转关键；陈敬之是苏清宁的后盾，在专业和精神上给予支持；林薇薇是苏清宁的闺蜜和法律支援。"
}"}

